ALTER TABLE "GameClock" ADD COLUMN "campusEpoch" TIMESTAMP(3), ADD COLUMN "campusStartWeek" INTEGER;
UPDATE "GameClock" SET "campusEpoch" = CURRENT_TIMESTAMP, "campusStartWeek" = GREATEST(1, FLOOR(EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - "startedAt")) / 604800)::INTEGER + 1);
ALTER TABLE "Character" ADD COLUMN "campusLook" TEXT;
CREATE TABLE "CampusLink" ("userId" TEXT PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE, "characterId" TEXT NOT NULL UNIQUE REFERENCES "Character"("id") ON DELETE CASCADE, "profileId" CHAR(64) NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CampusAssessment" ("id" BIGSERIAL PRIMARY KEY, "characterId" TEXT NOT NULL REFERENCES "Character"("id") ON DELETE CASCADE, "key" TEXT NOT NULL, "gameWeek" INTEGER NOT NULL, "score" INTEGER NOT NULL CHECK ("score" BETWEEN 0 AND 100), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("characterId", "key"));
